skip_unless_full_tests()

# Expected values are SymPy's outputs for the same calls (sympy/series/tests/test_kauers.py, test_approximants.py and acceleration);
# the rows come from the battery that compares this port with SymPy.

test_that("kauers: finite_diff matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(x^2 + 2*x + 1, x) })), "2*x + 3")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(y^3 + 2*y^2 + 3*y + 5, y) })), "3*y^2 + 7*y + 6")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(z^2 - 2*z + 3, z) })), "2*z - 1")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(w^2 + 3*w - 2, w) })), "2*w + 4")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(sin(x), x, sym_pi/6) })), "-sin(x) + sin(x + pi/6)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(cos(y), y, sym_pi/3) })), "-cos(y) + cos(y + pi/3)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(x^2 - 2*x + 3, x, 2) })), "4*x")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(n^2 - 2*n + 3, n, 3) })), "6*n + 3")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(x^3, x) })), "3*x^2 + 3*x + 1")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(x*y^2, y) })), "2*x*y + x")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(x*y^2, x, y) })), "y^3")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(exp(x), x) })), "-exp(x) + E*exp(x)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(2^x, x) })), "2^x")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(x^4 - x, x, -1) })), "-4*x^3 + 6*x^2 - 4*x + 2")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff((x + 1)^3, x) })), "3*x^2 + 9*x + 7")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(1/x, x) })), "1/(x + 1) - 1/x")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(x^2, x, Rational(1, 2)) })), "x + 1/4")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(5, x) })), "ERR AttributeError: 'int' object has no attribute 'expand'")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(x*sin(x), x) })), "-x*sin(x) + x*sin(x + 1) + sin(x + 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff(log(x), x, 2) })), "-log(x) + log(x + 2)")
})

test_that("kauers: finite_diff_kauers matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff_kauers(Sum(x^2, list(x, 1, n))) })), "(n + 1)^2")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff_kauers(Sum(y, list(y, 1, m))) })), "m + 1")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff_kauers(Sum((x*y), list(x, 1, m), list(y, 1, n))) })), "(m + 1)*(n + 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff_kauers(Sum((x*y^2), list(x, 1, m), list(y, 1, n))) })), "(m + 1)*(n + 1)^2")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff_kauers(Sum(1/k, list(k, 1, n))) })), "1/(n + 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff_kauers(Sum(sin(k), list(k, 0, n))) })), "sin(n + 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff_kauers(Sum(2^k*x, list(k, 0, m))) })), "2^(m + 1)*x")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff_kauers(Sum(k^3, list(k, 1, 2*n))) })), "(2*n + 1)^3")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff_kauers(Sum(x^k, list(k, 0, n))) })), "x^(n + 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); finite_diff_kauers(Sum(k*z, list(k, 1, n), list(z, 0, m))) })), "(m + 1)*(n + 1)")
})

test_that("acceleration: richardson matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); N(richardson((1 + 1/n)^n, n, 10, 20), 20) })), "2.7182818284590452354")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); richardson((1 + 1/n)^n, n, 10, 3) })), "64760917612327084418953891207076443/23824634392675154069619793920000000")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); richardson(1/n, n, 1, 2) })), "0")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); richardson(1 - 1/n^2, n, 5, 4) })), "1")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); richardson(n/(n + 1), n, 3, 0) })), "3/4")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); richardson(n/(n + 1), n, 3, 1) })), "19/20")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); richardson(x + 1/n, n, 2, 2) })), "x")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); richardson(Sum(1/k^2, list(k, 1, n)), n, 5, 3) })), "870493/529200")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); N(richardson(Sum(1/k^2, list(k, 1, n)), n, 10, 10), 15) })), "1.64493406684822")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); richardson(Sum(1/factorial(k), list(k, 0, n)), n, 2, 2) })), "8/3")
})

test_that("acceleration: shanks matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); N(shanks(Sum(Integer(-1)^(k + 1) / k, list(k, 1, n)), n, 25), 10) })), "0.6931396564")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); N(shanks(Sum(Integer(-1)^(k + 1) / k, list(k, 1, n)), n, 25, 5), 15) })), "0.693147180559945")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); shanks(Sum(Integer(-1)^(k + 1) / k, list(k, 1, n)), n, 3) })), "29/42")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); shanks(Sum(Integer(-1)^(k + 1) / k, list(k, 1, n)), n, 4, 2) })), "2071/2988")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); shanks(1 - 1/n, n, 4) })), "7/8")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); shanks(Sum(Rational(1, 2)^k, list(k, 0, n)), n, 3) })), "2")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); shanks(Sum(x^k, list(k, 0, n)), n, 1) })), "(x^2 + x - (x + 1)^2 + 1)/(x^2 - x)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); shanks(Sum(4*Integer(-1)^k/(2*k + 1), list(k, 0, n)), n, 6, 3) })), "6697843223/2131989860")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); shanks(Sum(1/factorial(k), list(k, 0, n)), n, 3, 1) })), "49/18")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); m <- Symbol("m"); n <- Symbol("n"); w <- Symbol("w"); k <- Symbol("k"); shanks(n^2, n, 2) })), "-7/2")
})

test_that("approximants: pade_approximants_gcdex matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); lapply(pade_approximants_gcdex(Poly(1 + x + x^2/2 + x^3/6 + x^4/24 + x^5/120, x), 5), function(pq) .pyT(lapply(pq, as_expr))) })), "[(x^5/120 + x^4/24 + x^3/6 + x^2/2 + x + 1, 1), (5*x^4 + 40*x^3 + 180*x^2 + 480*x + 600, 600 - 120*x), (x^3/15 + 3*x^2/5 + 12*x/5 + 4, x^2/5 - 8*x/5 + 4), (45*x^2 + 360*x + 900, -15*x^3 + 135*x^2 - 540*x + 900), (8*x/15 + 8/3, x^4/45 - 8*x^3/45 + 4*x^2/5 - 32*x/15 + 8/3), (225, -15*x^5/8 + 75*x^4/8 - 75*x^3/2 + 225*x^2/2 - 225*x + 225)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); lapply(pade_approximants_gcdex(Poly(x - x^3/6 + x^5/120, x), 6), function(pq) .pyT(lapply(pq, as_expr))) })), "[(x^5/120 - x^3/6 + x, 1), (280*x^3 - 2400*x, -120*x^2 - 2400), (9*x/49, x^4/280 + 3*x^2/98 + 9/49)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); lapply(pade_approximants_gcdex(Poly(1 + x + x^2/2 + x^3/6 + x^4/24, x), 4), function(pq) .pyT(lapply(pq, as_expr))) })), "[(x^4/24 + x^3/6 + x^2/2 + x + 1, 1), (4*x^3 + 24*x^2 + 72*x + 96, 96 - 24*x), (x^2/4 + 3*x/2 + 3, x^2/4 - 3*x/2 + 3), (24*x + 96, -4*x^3 + 24*x^2 - 72*x + 96), (1, x^4/24 - x^3/6 + x^2/2 - x + 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); lapply(pade_approximants_gcdex(Poly(1 + x^3 + x^6/2, x), 7), function(pq) .pyT(lapply(pq, as_expr))) })), "[(x^6/2 + x^3 + 1, 1), (-2*x^5 - 2*x^2, -2*x^2), (x^3/2 + 1, 1 - x^3/2), (2*x^2, -2*x^5 + 2*x^2), (1, x^6/2 - x^3 + 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); lapply(pade_approximants_gcdex(Poly(2 + 2*x/5 - 2*x^2/25 + 8*x^3/375 - 4*x^4/625 + 32*x^5/15625 - 32*x^6/46875, x), 6), function(pq) .pyT(lapply(pq, as_expr))) })), "[(-32*x^6/46875 + 32*x^5/15625 - 4*x^4/625 + 8*x^3/375 - 2*x^2/25 + 2*x/5 + 2, 1), (-3*x^5/8 + 25*x^4/8 - 375*x^3/16 + 1875*x^2/8 + 9375*x/2 + 140625/16, 46875*x/32 + 140625/32), (4*x^4/675 - 8*x^3/45 - 98*x^2/9 - 550*x/9 - 250/3, -8*x^2/3 - 200*x/9 - 125/3), (-3825*x^3/4 - 37125*x^2/2 - 84375*x - 421875/4, -675*x^3/4 - 10125*x^2/2 - 253125*x/8 - 421875/8), (-4966*x^2/867 - 31150*x/867 - 14750/289, -4*x^4/3825 + 88*x^3/4335 - 1138*x^2/867 - 11150*x/867 - 7375/289), (18231384375*x/6165289 + 39990375000/6165289, 867*x^5/4966 - 13503525*x^4/12330578 + 36088875*x^3/6165289 - 447046875*x^2/12330578 + 10233309375*x/12330578 + 19995187500/6165289), (308264450/1453973161, 6165289*x^6/18231384375 - 2022214792*x^5/2726199676875 + 178793381*x^4/109047987075 - 80148757*x^3/21809597415 + 12330578*x^2/1453973161 - 30826445*x/1453973161 + 154132225/1453973161)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); lapply(pade_approximants_gcdex(Poly(1 + 2*x + 3*x^2 + 4*x^3, x), 3), function(pq) .pyT(lapply(pq, as_expr))) })), "[(4*x^3 + 3*x^2 + 2*x + 1, 1), (x^2/16 + x/8 + 3/16, 3/16 - x/4), (16, 16*x^2 - 32*x + 16)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); lapply(pade_approximants_gcdex(Poly(x, x), 2), function(pq) .pyT(lapply(pq, as_expr))) })), "[(x, 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); lapply(pade_approximants_gcdex(Poly(1 - x, x), 1), function(pq) .pyT(lapply(pq, as_expr))) })), "[(1 - x, 1), (1, x + 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); lapply(pade_approximants_gcdex(Poly(1 + x + x^2, x), 5), function(pq) .pyT(lapply(pq, as_expr))) })), "[(x^2 + x + 1, 1), (1, -x^4 + x^3 - x + 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); lapply(pade_approximants_gcdex(Poly(1 + x + x^2 + x^3 + x^4, x), 2), function(pq) .pyT(lapply(pq, as_expr))) })), "[(x^2 + x + 1, 1), (1, 1 - x)]")
})

test_that("approximants: pade_approximant_gcdex matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(1 + x + x^2/2 + x^3/6 + x^4/24, x), 2), as_expr)) })), "(x^2/4 + 3*x/2 + 3, x^2/4 - 3*x/2 + 3)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(1 + x^3 + x^6/2, x), 3, 4), as_expr)) })), "(x^3/2 + 1, 1 - x^3/2)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(2 + 2*x/5 - 2*x^2/25 + 8*x^3/375 - 4*x^4/625 + 32*x^5/15625 - 32*x^6/46875, x), 3), as_expr)) })), "(-3825*x^3/4 - 37125*x^2/2 - 84375*x - 421875/4, -675*x^3/4 - 10125*x^2/2 - 253125*x/8 - 421875/8)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(x - x^3/6 + x^5/120, x), 0, 4), as_expr)) })), "ERR ValueError: polynomial f=Poly(1/120*x^5 - 1/6*x^3 + x, x, domain='QQ') has zero of order 1, which is greater than 0, the requested order of the numerator.")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(1 + x + x^2/2 + x^3/6 + x^4/24 + x^5/120, x), 1, 1), as_expr)) })), "(2*x + 4, 4 - 2*x)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(1 + x + x^2/2 + x^3/6 + x^4/24 + x^5/120, x), 2, 3), as_expr)) })), "(45*x^2 + 360*x + 900, -15*x^3 + 135*x^2 - 540*x + 900)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(1 + x + x^2/2 + x^3/6 + x^4/24 + x^5/120, x), 3, 2), as_expr)) })), "(x^3/15 + 3*x^2/5 + 12*x/5 + 4, x^2/5 - 8*x/5 + 4)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(1 + x + x^2/2 + x^3/6 + x^4/24 + x^5/120, x), 5, 0), as_expr)) })), "(x^5/120 + x^4/24 + x^3/6 + x^2/2 + x + 1, 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(1 + x + x^2/2 + x^3/6 + x^4/24 + x^5/120, x), 0, 5), as_expr)) })), "(225, -15*x^5/8 + 75*x^4/8 - 75*x^3/2 + 225*x^2/2 - 225*x + 225)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(x - x^3/6 + x^5/120, x), 3, 2), as_expr)) })), "(-7*x^3/60 + x, x^2/20 + 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(x - x^3/6 + x^5/120, x), 1, 2), as_expr)) })), "(x, x^2/6 + 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(1 + 2*x + 3*x^2 + 4*x^3, x), 1, 2), as_expr)) })), "(x^2/16 + x/8 + 3/16, 3/16 - x/4)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(1 + x + x^2/2 + x^3/6 + x^4/24 + x^5/120, x), -1, 2), as_expr)) })), "ERR ValueError: m=-1 and n=2 must be non-negative integers.")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(x^2 + x^3, x), 1, 1), as_expr)) })), "ERR ValueError: polynomial f=Poly(x^3 + x^2, x, domain='QQ') has zero of order 2, which is greater than 1, the requested order of the numerator.")
  expect_identical(.pyrun(local({ x <- Symbol("x"); .pyT(lapply(pade_approximant_gcdex(Poly(x^2 + x^3, x), 2, 1), as_expr)) })), "(x^2, 1 - x)")
})

test_that("approximants: pade_approximant matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(exp(x), x, 0, 2) })), "(x^2/4 + 3*x/2 + 3)/(x^2/4 - 3*x/2 + 3)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(exp(sin(x^3)), x, 0, 3, 4) })), "(x^3/2 + 1)/(1 - x^3/2)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(log(1 + x), x, 0, 3) })), "(-396*x^3/25 - 432*x^2/5 - 432*x/5)/(-108*x^3/25 - 1296*x^2/25 - 648*x/5 - 432/5)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(log(x), x, 1, 3) })), "(-432*x/5 - 396*(x - 1)^3/25 - 432*(x - 1)^2/5 + 432/5)/(-648*x/5 - 108*(x - 1)^3/25 - 1296*(x - 1)^2/25 + 216/5)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(exp(x)/x, x, 0, 2, 3) })), "(x^2/4 + 3*x/2 + 3)/(x*(x^2/4 - 3*x/2 + 3))")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(sin(x), x, 0, 0, 4) })), "ERR ValueError: polynomial f=Poly(-1/6*x^3 + x, x, domain='QQ') has zero of order 1, which is greater than 0, the requested order of the numerator.")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(1/x, x, 0, 1, 0) })), "ERR ValueError: Expression f=1/x has pole of order 1, which is greater than 0, the requested order of the denominator.")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(exp(x), x) })), "(x^6/14400 + 7*x^5/2400 + 7*x^4/120 + 7*x^3/10 + 21*x^2/4 + 231*x/10 + 231/5)/(x^6/14400 - 7*x^5/2400 + 7*x^4/120 - 7*x^3/10 + 21*x^2/4 - 231*x/10 + 231/5)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(cos(x), x, 0, 2, 2) })), "(1 - 5*x^2/12)/(x^2/12 + 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(1/(1 - x), x, 0, 1, 1) })), "x^2 + x + 1")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(atan(x), x, 0, 3, 2) })), "(4*x^3/15 + x)/(3*x^2/5 + 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(exp(x), x, 1, 1, 1) })), "(2*x + 2)/(-2*(x - 1)*exp(-1) + 4*exp(-1))")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(tan(x), x, 0, 3, 2) })), "(-x^3/15 + x)/(1 - 2*x^2/5)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(sqrt(1 + x), x, 0, 1, 1) })), "(24*x + 32)/(8*x + 32)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(exp(-x), x, 0, 2, 2) })), "(x^2/4 - 3*x/2 + 3)/(x^2/4 + 3*x/2 + 3)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(x*exp(x), x, 0, 2, 1) })), "(2*x^2 + 4*x)/(4 - 2*x)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(sin(x)/x, x, 0, 2, 2) })), "(1 - 7*x^2/60)/(x^2/20 + 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(cos(x)/x^2, x, 0, 2, 3) })), "(1 - x^2/2)/x^2")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(sqrt(x), x, 0, 1, 1) })), "ERR ValueError: f=sqrt(x) does not have a laurent expansion in x around x0.")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(exp(x), x, 0, -1, 1) })), "ERR ValueError: m=-1 and n=1 must be non-negative integers")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(log(1 + x), x, 0, 2, 2) })), "(-27*x^2/2 - 27*x)/(-9*x^2/2 - 27*x - 27)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); pade_approximant(sinh(x), x, 0, 3, 2) })), "(7*x^3/60 + x)/(1 - x^2/20)")
})

test_that("approximants: approximants matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); approximants(lapply(0:15, lucas)) })), "[2, -4/(x - 2), (5*x - 2)/(3*x - 1), (x - 2)/(x^2 + x - 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); approximants(lapply(0:15, function(k) lucas(k) + fibonacci(k + 2))) })), "[3, -3/(x - 1), (3*x - 3)/(2*x - 1), -3/(x^2 + x - 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); approximants(lapply(0:15, function(k) lucas(k)^2)) })), "[4, -16/(x - 4), (35*x - 4)/(9*x - 1), (37*x - 28)/(13*x^2 + 11*x - 7), (50*x^2 + 63*x - 52)/(37*x^2 + 19*x - 13), (-x^2 - 7*x + 4)/(x^3 - 2*x^2 - 2*x + 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); approximants(list(1, 1, 2, 3, 5, 8, 13, 21)) })), "[1, -1/(x - 1), (x - 1)/(2*x - 1), -1/(x^2 + x - 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); approximants(list(1, 2, 3, 4, 5, 6)) })), "[1, -1/(2*x - 1), (x + 2)/(2 - 3*x), 1/(x^2 - 2*x + 1)]")
  expect_identical(.pyrun(local({ x <- Symbol("x"); approximants(list(1, 1, 2, 5, 14, 42, 132)) })), "[1, -1/(x - 1), (x - 1)/(2*x - 1), (1 - 2*x)/(x^2 - 3*x + 1), (x^2 - 3*x + 1)/(3*x^2 - 4*x + 1), (-3*x^2 + 4*x - 1)/(x^3 - 6*x^2 + 5*x - 1), (x^3 - 6*x^2 + 5*x - 1)/(4*x^3 - 10*x^2 + 6*x - 1)]")
})

